header('Content-Type: application/json; charset=utf-8');header('Access-Control-Allow-Origin: http://localhost:5173');header('Access-Control-Allow-Credentials: true');header('Access-Control-Allow-Headers: Content-Type');header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS');if($_SERVER['REQUEST_METHOD']==='OPTIONS')exit;
function body():array{$d=json_decode(file_get_contents('php://input'),true);return is_array($d)?$d:$_POST;}function json_out($data,int $status=200):never{http_response_code($status);echo json_encode($data);exit;}function require_login():array{if(empty($_SESSION['user']))json_out(['message'=>'Please sign in first.'],401);return $_SESSION['user'];}function require_admin():array{$u=require_login();if(($u['role']??'')!=='admin')json_out(['message'=>'Admin access required.'],403);return $u;}function valid_email($v):bool{return filter_var($v,FILTER_VALIDATE_EMAIL)!==false;}
